   e. Add handleSimulate function:
```js
const handleSimulate = async () => {
  setSimLoading(true);
  setSimResult(null);
  try {
    const diseaseNameMap = { heart_attack: 'Heart Attack', diabetes: 'Diabetes', cancer: 'Cancer Screening' };
    // Build full params by merging original result input_parameters with simParams overrides
    const baseParams = result.input_parameters || {};
    let mergedParams = { ...baseParams };
    if (selectedDisease === 'heart_attack') {
      if (simParams.systolicBp != null) mergedParams.systolic_bp = Number(simParams.systolicBp);
      if (simParams.diastolicBp != null) mergedParams.diastolic_bp = Number(simParams.diastolicBp);
      if (simParams.cholesterol != null) mergedParams.cholesterol = Number(simParams.cholesterol);
      if (simParams.maxHeartRate != null) mergedParams.max_heart_rate = Number(simParams.maxHeartRate);
    } else if (selectedDisease === 'diabetes') {
      if (simParams.glucose != null) mergedParams.glucose = Number(simParams.glucose);
      if (simParams.hba1c != null) mergedParams.hba1c = Number(simParams.hba1c);
      if (simParams.bmi != null) mergedParams.bmi = Number(simParams.bmi);
    } else if (selectedDisease === 'cancer') {
      if (simParams.alcohol != null) mergedParams.alcohol = simParams.alcohol;
      if (simParams.toxinExposure != null) mergedParams.exposure = simParams.toxinExposure;
      if (simParams.smoking != null) mergedParams.smoking = simParams.smoking;
    }
    const res = await api.post('/predictions/simulate/', {
      disease_type: diseaseNameMap[selectedDisease],
      parameters: mergedParams
    });
    setSimResult(res.data);
  } catch(err) {
    console.error('Simulation failed', err);
  } finally {
    setSimLoading(false);
  }
};
```
